import pathlib,hashlib,json
r=pathlib.Path('研究尝试/方向1_超跌反弹/inputs_pre2025/execution_rules_2020_2024');o=pathlib.Path('研究尝试/方向1_超跌反弹/execution_rules_research_2020_2024')
m=json.loads((r/'CODE_MANIFEST.json').read_text(encoding='utf-8-sig'))
for v in m['files']:assert hashlib.sha256((r/v['path']).read_bytes()).hexdigest()==v['sha256']
s=(r/'ACCOUNT_ENGINE_REFERENCE.py').read_text(encoding='utf-8-sig')
s=s.replace('    no_price_limit:bool=False','    upper_limit:object=None\n    no_price_limit:bool=False')
s=s.replace('    pending_factor_action:bool=False','    pending_factor_action:bool=False\n    trailing_wealth:Decimal=ZERO')
s=s.replace("*,scope='all',verified_suspensions=None,policy_verified=False):","*,scope='all',verified_suspensions=None,policy_verified=False,tp=.20,sl=None,horizon=20,rank='code',trail=False):")
s=s.replace("def target(p):return ceil_price((p.buy_gross*Decimal('1.20')-p.dividend_gross)/p.qty())","def target(p):return ceil_price((p.buy_gross*(1+dec(tp))-p.dividend_gross)/p.qty())\n\n    def stop(p):\n        if sl is None:return ZERO\n        wealth=max(p.buy_gross,p.trailing_wealth) if trail else p.buy_gross\n        return money((wealth*(1-dec(sl))-p.dividend_gross)/p.qty())\n\n    def sortkey(e):\n        if rank=='liquid':return (-float(e.get('amount20',0)),e['code'])\n        if rank=='deep':return (float(e.get('ret20',0)),e['code'])\n        return (e['code'],)")
s=s.replace("elif dec(b.open)>=target(p):", "elif sl is not None and dec(b.open)<=stop(p):\n                if dec(b.open)>limit:sell(p,day,b.open,'stop_loss_open','open')\n                elif dec(b.high)>limit:intraday_deferred.add(code)\n                else:delay(p,day,'sealed_lower_limit_stop')\n            elif dec(b.open)>=target(p):")
s=s.replace("sell(p,day,b.open,'take_profit_open','open')","sell(p,day,target(p),'take_profit_open','open')")
s=s.replace("sorted(schedule.get(day,[]),key=lambda x:x['code'])","sorted(schedule.get(day,[]),key=sortkey)")
s=s.replace("            if (code,int(day[:4])) not in coverage:raise AuditBlocked(f'Missing entry code/year corporate evidence {code} {day}')","            if b.upper_limit is not None and dec(b.open)>=dec(b.upper_limit):\n                skips.append(dict(date=day,code=code,reason='upper_limit_open_conservative_no_fill'));continue\n            if (code,int(day[:4])) not in coverage:raise AuditBlocked(f'Missing entry code/year corporate evidence {code} {day}')")
s=s.replace("j=ordinal[day]+20;", "j=ordinal[day]+horizon;")
s=s.replace("p.lots=[Lot(code+':'+day,qty,day,day)];", "p.trailing_wealth=gross;p.lots=[Lot(code+':'+day,qty,day,day)];")
s=s.replace("            tp=target(p)\n            if dec(b.high)>=tp:","            stop_price=stop(p)\n            if sl is not None and dec(b.low)<=stop_price:\n                if stop_price>limit:sell(p,day,min(dec(b.open),stop_price),'stop_loss_touch','intraday');continue\n                if dec(b.high)>limit:sell(p,day,limit,'stop_loss_limit_break_proxy','intraday');continue\n                delay(p,day,'sealed_lower_limit_stop');continue\n            tp_price=target(p)\n            if dec(b.high)>=tp_price:")
s=s.replace("if tp>limit:sell(p,day,tp,", "if tp_price>limit:sell(p,day,tp_price,")
s=s.replace("if b is not None:p.last_price=money(b.close)","if b is not None:\n                p.last_price=money(b.close)\n                p.trailing_wealth=max(p.trailing_wealth,money(p.qty()*p.last_price)+p.dividend_gross)")
s=s.replace("take_profit=.20,forced_day=20", "take_profit=tp,stop_loss=sl,trailing=trail,rank=rank,forced_day=horizon")
s=s.replace("or dec(b.high)>=target(p):delay(p,day,'locked_shares_exit')","or dec(b.high)>=target(p) or (sl is not None and dec(b.low)<=stop(p)):delay(p,day,'locked_shares_exit')")
(o/'account_engine.py').write_text(s,encoding='utf-8')
print(hashlib.sha256(s.encode()).hexdigest())
